   320	/** Initialize our pusher subscriptions to listen for someone typing in a report. */
   321	function subscribeToReportTypingEvents(reportID: string) {
   322	    if (!reportID) {
   323	        return;
   324	    }
   325	
   326	    // Make sure we have a clean Typing indicator before subscribing to typing events
   327	    Onyx.set(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, {});
   328	
   329	    const pusherChannelName = getReportChannelName(reportID);
   330	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_TYPING, (typingStatus) => {
   331	        // If the pusher message comes from OldDot, we expect the typing status to be keyed by user
   332	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   333	        // since personal details are keyed by accountID.
   334	        const normalizedTypingStatus = getNormalizedStatus(typingStatus);
   335	        const accountIDOrLogin = Object.keys(normalizedTypingStatus).at(0);
   336	
   337	        if (!accountIDOrLogin) {
   338	            return;
   339	        }
   340	
   341	        // Don't show the typing indicator if the user is typing on another platform
   342	        if (Number(accountIDOrLogin) === currentUserAccountID) {
   343	            return;
   344	        }
   345	
   346	        // Use a combo of the reportID and the accountID or login as a key for holding our timers.
   347	        const reportUserIdentifier = `${reportID}-${accountIDOrLogin}`;
   348	        clearTimeout(typingWatchTimers[reportUserIdentifier]);
   349	        Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, normalizedTypingStatus);
   350	
   351	        // Wait for 1.5s of no additional typing events before setting the status back to false.
   352	        typingWatchTimers[reportUserIdentifier] = setTimeout(() => {
   353	            const typingStoppedStatus: ReportUserIsTyping = {};
   354	            typingStoppedStatus[accountIDOrLogin] = false;
   355	            Onyx.merge(`${ONYXKEYS.COLLECTION.REPORT_USER_IS_TYPING}${reportID}`, typingStoppedStatus);
   356	            delete typingWatchTimers[reportUserIdentifier];
   357	        }, 1500);
   358	    }).catch((error: ReportError) => {
   359	        Log.hmmm('[Report] Failed to initially subscribe to Pusher channel', {errorType: error.type, pusherChannelName});
   360	    });
   361	}
